<script setup lang="ts">
import type {Collection} from '~/shared/types'
const api=useApi(),selected=ref(''),busy=ref(false),message=ref(''),actionError=ref('')
const {data:collections,pending,error,refresh}=await useAsyncData('admin-collections',()=>api.collections())
const {data:products,refresh:refreshProducts}=await useAsyncData('collection-products',()=>api.adminProducts({pageSize:50}))
const blank=()=>({id:'',slug:'',name:'',description:'',cover:'/assets/collection-archive.webp',isFeatured:true,productIds:[] as string[]})
const form=reactive(blank())
function edit(c?:Collection){selected.value=c?.id||'';Object.assign(form,c?{...c,productIds:products.value?.items.filter(p=>p.collectionIds.includes(c.id)).map(p=>p.id)||[]}:blank());message.value='';actionError.value=''}
async function save(){busy.value=true;actionError.value='';message.value='';try{const c=await api.saveCollection({...form},selected.value||undefined);selected.value=c.id;form.id=c.id;await Promise.all([refresh(),refreshProducts()]);clearNuxtData(k=>k.startsWith('catalog-')||k==='collections'||k.startsWith('home-'));message.value='Коллекция сохранена и доступна в магазине.'}catch(e){actionError.value=errorMessage(e)}finally{busy.value=false}}
useSeoMeta({title:'Коллекции — демо-панель Deadlock Family'})
</script>
<template><AdminShell title="Коллекции"><ApiState :pending="pending" :error="error" @retry="refresh()"/><div class="collection-admin-grid"><div class="collection-list"><button v-for="c in collections" :key="c.id" :class="{selected:selected===c.id}" @click="edit(c)"><h3>{{c.name}}</h3><p>{{c.description}}</p></button><button @click="edit()"><h3>+ Новая коллекция</h3><p>Создать ещё одну историю</p></button></div><form class="form-panel form-stack" @submit.prevent="save"><h2>{{selected?'Редактировать коллекцию':'Новая коллекция'}}</h2><label class="field">Название *<input v-model="form.name" required maxlength="120"></label><label class="field">Slug латиницей *<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="120" placeholder="my-collection"></label><label class="field">Описание<textarea v-model="form.description" maxlength="2000"/></label><label class="field">Обложка<select v-model="form.cover"><option value="/assets/collection-essentials.webp">Символы семьи</option><option value="/assets/collection-archive.webp">Архив</option><option value="/assets/collection-collectors.webp">Коллекционные вещи</option><option value="/assets/archivist.webp">Хранитель архива</option></select></label><img :src="form.cover" class="image-preview" alt="Обложка коллекции"><label class="check-label"><input v-model="form.isFeatured" type="checkbox">Показывать на главной странице</label><div><p class="sidebar-label">Товары коллекции</p><div class="product-checkboxes"><label v-for="p in products?.items" :key="p.id" class="check-label"><input v-model="form.productIds" type="checkbox" :value="p.id">{{p.name}}</label></div></div><p v-if="actionError" class="notice error" role="alert">{{actionError}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><button class="btn btn-primary" :disabled="busy">{{busy?'Сохраняем…':'Сохранить коллекцию'}}</button></form></div></AdminShell></template>
